cd /Users/mizuki-y/.dot.d/emacs.d/elpa/agent-shell-20260911.1130 && for f in agent-shell-switch-buffer agent-shell-project-buffers agent-shell-send-file agent-shell-send-region-to agent-shell-send-clipboard-image agent-shell-send-screenshot agent-shell-interrupt agent-shell-copy-last-output agent-shell-toggle-logging; do
