  awk -v fn="$f" '
    $0 ~ "\\(defun[[:space:]]+"fn"[[:space:]]*\\(" {p=1}
    p { print; c++ }
    p && c>1 && /\(interactive/ {print "  --> HAS interactive"; exit}
    p && c>6 {print "  --> no interactive found in first lines"; exit}
  ' agent-shell.el
done

for f in agent-shell-project-buffers agent-shell-send-file agent-shell-send-clipboard-image agent-shell-send-screenshot agent-shell-copy-last-output; do
  echo "== $f =="
  awk -v fn="$f" '
    $0 ~ "^\\(defun[[:space:]]+"fn"[[:space:]]*\\(" {p=1; print; next}
    p && /^\(defun / {exit}
    p {print}
  ' agent-shell.el | grep -n "interactive" 
  echo "---"
done

for f in agent-shell-new-shell agent-shell-fork agent-shell-restart agent-shell-reload; do
